    val entries: List<KnowledgeEntry> = listOf(
        KnowledgeEntry("gmtk-001-space-invaders-difficulty-curve", "Space Invaders", "00:02:40", "00:03:35", listOf("difficulty-curve", "pacing", "tension-and-release", "level-design"), listOf("difficulty", "pacing", "scope_structure"), "Raising challenge steadily without wearing the player out.", "Each cleared enemy makes the rest move faster, and every new wave starts with the enemies lower on the screen than the one before.", "Pressure climbs through a wave and drops back when a new wave begins, giving a repeating pattern of strain and short recovery.", null, null, "Should difficulty rise without pause, or step back at set moments so players can recover?", listOf("gmtk-007-tetris-two-kinds-of-difficulty"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-002-pac-man-role-reversal", "Pac-Man", "00:03:48", "00:04:39", listOf("role-reversal", "variety", "tension-and-release", "power-fantasy"), listOf("progression", "pacing", "theme_message"), "Keeping a very simple game from feeling one-note.", "The player is hunted by the ghosts until collecting a special pellet, which briefly turns the ghosts into targets that can be eaten for points.", "The brief swap between fear and dominance adds variety and gives the game an emotional swing between weakness and strength.", null, null, "Is there a moment in your game when the player's position of power could briefly flip?", listOf(), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-003-rogue-procedural-permadeath", "Rogue", "00:04:53", "00:06:01", listOf("procedural-generation", "permadeath", "replayability"), listOf("difficulty", "replayability"), "Making each playthrough different and preventing players from simply memorising the level.", "Dungeons are built by rule from rooms, corridors, items and monsters, and dying means starting over in a freshly built dungeon, with no saves, checkpoints or respawns.", "No two runs match, and knowledge of a specific layout cannot be rehearsed into an easy win.", null, "Permanent loss raises the stakes of each decision; whether that suits a given audience is a separate judgement.", "Should every run be newly generated, and should failure send the player all the way back?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-004-super-mario-bros-expressive-jump", "Super Mario Bros.", "00:06:06", "00:06:58", listOf("expressive-movement", "game-feel", "physics", "platforming"), listOf("emergence", "game_feel", "movement"), "Making one basic action enjoyable enough to build a whole game on.", "How high Mario jumps depends on how long the button stays pressed, how far depends on his running speed, and the player can still steer while airborne.", "A simple leap becomes a wide range of controllable motions, which is fun and skill-testing enough to carry a game, even a genre.", null, null, "Which single action in your game should feel best, and how much control should the player have over it?", listOf("gmtk-020-tony-hawk-feel-on-the-thumbs"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-005-zelda-freedom-and-curiosity", "The Legend of Zelda", "00:07:29", "00:08:35", listOf("player-freedom", "exploration", "nonlinear-order", "onboarding"), listOf("exploration", "onboarding"), "Making the player's route through a game feel self-authored.", "The player starts in an open area with almost no instructions and may head anywhere and attempt challenges in any sequence, though some areas stay closed until an item is found and dungeons carry numbers.", "The journey feels personal because it is steered by curiosity instead of by a designer's script.", "The freedom is bounded: some obstacles need specific items, dangerous enemies punish unprepared players, and the dungeons have a suggested order.", null, "How much freedom should the player have over where to go and in what order?", listOf("gmtk-006-mega-man-choose-your-order", "gmtk-009-super-metroid-explore-and-unlock"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-006-mega-man-choose-your-order", "Mega Man", "00:08:39", "00:09:45", listOf("nonlinear-order", "player-freedom", "replayability", "level-design"), listOf("exploration", "replayability", "scope_structure"), "Moving beyond the fixed level-after-level order common in platformers.", "The game opens on a menu of six boss stages that may be played in any order.", "Players gain a sense of control and a reason to replay, because a new order changes how the game plays.", "The video says the idea is imperfect: players quickly circulated an optimal route.", null, "Should players pick the order of your challenges, and what stops one order from being obviously best?", listOf("gmtk-006b-mega-man-boss-powers-as-counters", "gmtk-005-zelda-freedom-and-curiosity"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-006b-mega-man-boss-powers-as-counters", "Mega Man", "00:08:50", "00:09:31", listOf("progression", "player-freedom", "systemic-interactions", "replayability"), listOf("progression", "emergence", "game_feel", "replayability"), "Making the chosen order of challenges matter.", "Beating a boss gives the player that boss's weapon, which works especially well against certain other bosses and helps in other stages.", "Earlier choices change the difficulty of later ones, so ordering becomes a real decision.", null, "As with free ordering, a best route can appear once players learn which weapon counters which boss.", "Should beating one challenge change how the next ones play?", listOf("gmtk-006-mega-man-choose-your-order"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-007-tetris-two-kinds-of-difficulty", "Tetris", "00:09:52", "00:11:05", listOf("difficulty-curve", "diegetic-difficulty", "systemic-interactions", "feedback"), listOf("difficulty", "emergence", "game_feel"), "Raising difficulty in a way players can see and understand.", "Speed is increased by the designer after a number of cleared lines, and separately the game gets harder by itself as the stack of pieces fills the space and leaves less time. Snake behaves the same way as its body grows.", "Part of the rise is imposed from outside and part follows naturally from the rules, which makes the ramp transparent and easy to grasp.", null, null, "Should difficulty come from designer-set numbers, from the state of the play space, or from both?", listOf("gmtk-001-space-invaders-difficulty-curve"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-008-doom-speed-and-space", "Doom", "00:11:12", "00:12:21", listOf("speed-and-flow", "enemy-design", "game-feel", "combat"), listOf("pacing", "game_feel", "movement", "combat"), "Making combat feel frantic and energetic.", "A very quick player character faces enemies that depend on distance and positioning, for example one that must be kept away from and another whose slow projectiles can be sidestepped.", "Fights feel fast and tense, and the movement itself is a source of enjoyment.", null, null, "How fast should the player move, and how do your enemies give that speed a purpose?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-009-super-metroid-explore-and-unlock", "Super Metroid", "00:12:25", "00:13:45", listOf("exploration", "progression-gating", "level-design", "world-structure"), listOf("exploration", "progression", "scope_structure"), "Building a game loop around the pleasure of exploring.", "The whole game is one connected map with barriers such as special doors and dangerous rooms; players search elsewhere for an item that lets them return, and doing so yields an upgrade or opens more of the map.", "A repeating cycle of exploring and gaining abilities that relies on the player remembering the map, and that underpins the Metroidvania genre.", null, null, "Should your world be one connected map opened up by abilities, or a set of separate levels?", listOf("gmtk-005-zelda-freedom-and-curiosity"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-010-pokemon-trading-community", "Pokemon Blue", "00:13:49", "00:15:18", listOf("community", "cooperation", "social-design", "collection"), listOf("progression", "multiplayer"), "Building community around a game, beyond competition.", "The game ships as two nearly identical versions, each with exclusive creatures; some creatures evolve only through trading and the starter creatures never reappear, so players must swap over a cable.", "Players ask each other for help and trade, which turns the game into something shared.", null, null, "Is there a reason for your players to help or trade with each other?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-011-mario-64-vs-tomb-raider-movement", "Tomb Raider (contrasted with Super Mario 64)", "00:15:18", "00:16:33", listOf("movement", "platforming", "3d-movement", "game-feel"), listOf("game_feel", "movement"), "Designing movement for fully three-dimensional spaces.", "Super Mario 64 offers quick, springy, flowing movement; Tomb Raider asks for careful positioning and exact, deliberate inputs.", "The same kind of 3D obstacle course can feel very different; the more deliberate style can still be rewarding once the player settles into it.", "Exacting movement can seem dated and irritating next to modern games that snap to ledges and climb automatically.", null, "Should movement be fluid and forgiving, or exact and demanding?", listOf("gmtk-004-super-mario-bros-expressive-jump"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-012-resident-evil-scarce-resources", "Resident Evil", "00:16:33", "00:17:48", listOf("resource-scarcity", "tension", "horror", "inventory"), listOf("pacing", "stealth_horror", "survival_resources"), "Making players feel afraid and uneasy.", "Ammunition and healing items are scarce and the inventory is a very small grid, so the player conserves ammo, weighs each shot, sometimes flees, and decides carefully what to carry.", "Turning the supply of resources up or down changes how strong or weak the player feels.", null, null, "How scarce should key resources be, and what should that do to how the player feels?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-013-half-life-no-cutscenes", "Half-Life", "00:18:00", "00:19:06", listOf("narrative", "immersion", "player-agency", "presentation"), listOf("narrative", "choice", "interface", "theme_message"), "Telling a story with the strengths of games rather than borrowing from film.", "The story is shown continuously from the hero's own viewpoint, with no cutscenes or level breaks; characters speak toward the camera and events happen in real time.", "A grounded, immersive feel in which the player never loses control.", null, null, "Should your story ever take control away from the player?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-014-thief-light-and-sound", "Thief: The Dark Project", "00:19:06", "00:20:04", listOf("stealth", "systemic-interactions", "environment", "player-expression"), listOf("exploration", "emergence", "game_feel", "stealth_horror"), "Making sneaking a readable and interesting way to play.", "Detection depends on two things: light (bright areas expose the player) and sound (hard floors carry footsteps). The player can alter conditions, for instance dousing a torch or laying moss to muffle steps.", "Play becomes careful watching, listening and reasoning about what the guards will do.", null, null, "What does the player need to observe, and what can they change to their advantage?", listOf("gmtk-016-deus-ex-player-freedom"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-015-crazy-taxi-concentrated-loop", "Crazy Taxi", "00:20:10", "00:21:18", listOf("short-session", "concentrated-loop", "onboarding", "score-chasing"), listOf("pacing", "onboarding", "replayability", "scope_structure"), "Hooking a player immediately and making them want another try, as arcade games must.", "The player collects fares and drives them to destinations within a few minutes; speed earns more money, stunts and risky driving add tips, and when the clock ends so does the session.", "A great deal of enjoyment from a very simple, tightly focused loop in a short time.", null, null, "What is the smallest loop that is fun by itself, and how long should one session last?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-016-deus-ex-player-freedom", "Deus Ex", "00:21:24", "00:22:52", listOf("player-agency", "player-freedom", "emergent-play", "level-design", "immersive-sim"), listOf("choice", "emergence", "scope_structure"), "Letting players meet an objective in whatever way they prefer.", "Open-ended levels offer many routes and solutions; the player can fight, sneak, talk their way through, or build skills like lockpicking and hacking to open other paths.", "Players feel strongly in charge; the designer's stated aim was for the game to reflect the player's cleverness more than the developers'.", null, null, "Should your levels support several different approaches to the same goal?", listOf("gmtk-014-thief-light-and-sound"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-017-diablo-2-skill-tree-power-fantasy", "Diablo II", "00:22:57", "00:24:25", listOf("progression", "skill-tree", "power-fantasy", "upgrade-systems"), listOf("progression", "theme_message"), "Making upgrades compelling and keeping players going.", "Each level-up raises stats and lets the player select a node in a visible skill tree, giving a new active ability or passive bonus, each capable of changing how the character plays.", "The sense of growing from weak to dominant, and curiosity about the next skill, keeps people playing.", null, null, "How should the player grow stronger, and should they be able to see what is coming?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-018-the-sims-player-led-play", "The Sims", "00:24:31", "00:25:45", listOf("emergent-play", "player-expression", "simulation", "sandbox"), listOf("emergence", "simulation_building"), "Supporting very different ways of playing the same game.", "A household simulation in which characters fulfil their own needs using utility-based AI; the player can watch or step in and direct them.", "Some players use it to tell stories and others to experiment on the characters, so the game becomes whatever the player makes of it.", null, null, "Should players be able to use your simulation in ways you did not plan for?", listOf(), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-019-gta-3-missions-and-sandbox", "Grand Theft Auto III", "00:25:45", "00:27:03", listOf("open-world", "sandbox", "mission-design", "fantasy-fit"), listOf("exploration", "emergence", "theme_message", "scope_structure"), "Making the time between missions in an open world worth playing.", "Scripted missions with goals, cutscenes, failure and rewards move the story on and open the map, while outside them the game invites mayhem through stunts, stolen vehicles and police chases.", "Free play is enjoyable because the setting and the player's role welcome chaos, which many open worlds lack.", null, null, "What will players want to do between your set challenges, and does your fantasy allow it?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-020-tony-hawk-feel-on-the-thumbs", "Tony Hawk's Pro Skater 3", "00:27:10", "00:28:34", listOf("game-feel", "input-design", "mastery", "score-chasing"), listOf("difficulty", "game_feel", "replayability", "interface"), "Making inputs satisfying in themselves.", "Tricks come from pressing a button with a direction, a manual from a quick stick motion, and a revert from a shoulder press timed to the moment of landing, all chainable into combos.", "Small, memorable inputs that feel good to perform, so players can return after years away and recover the skill quickly.", null, null, "Which inputs in your game should feel pleasing in their own right?", listOf("gmtk-004-super-mario-bros-expressive-jump"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-021-ico-design-by-subtraction", "Ico", "00:28:34", "00:29:48", listOf("subtraction", "minimalism", "relationship", "presentation"), listOf("narrative", "interface", "theme_message", "scope_structure"), "Finding a game's core by stripping away what is not needed.", "Following a design approach of removal, the game drops interface elements, and tells a relationship between two characters with no shared language through holding hands, simple commands and protecting her; saving is tied to the companion, so progress cannot be banked while she is gone.", "A bond built from actions, strengthened when the companion is taken away.", null, null, "What could you remove from your game to reveal what matters most?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-022-rez-synchronised-audio", "Rez", "00:30:04", "00:31:01", listOf("audio", "music-sync", "feedback", "trance-state"), listOf("game_feel", "theme_message"), "Pulling players into a deeply absorbed state.", "Shooting enemies triggers sounds that blend with the music in time, so the rhythm of play always matches the soundtrack.", "A meditative, immersive experience; the designer reports that the first working version already felt striking.", null, null, "Should the player's actions help create the music?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-023-silent-hill-2-unsettling-space", "Silent Hill 2", "00:31:05", "00:32:41", listOf("atmosphere", "horror", "level-design", "environment", "narrative"), listOf("exploration", "narrative", "stealth_horror", "theme_message", "scope_structure"), "Creating psychological horror.", "Long, quiet corridors, rooms with eerie noises but no creatures, thick fog that hides what lies ahead, and descents that go impossibly deep, all echoing the protagonist's guilt and trauma.", "The place itself is disturbing, and the player shares the character's mental state.", null, null, "Could the environment, not the enemies, produce the feeling you want?", listOf("gmtk-012-resident-evil-scarce-resources"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-024-animal-crossing-leisurely-pace", "Animal Crossing", "00:32:46", "00:34:11", listOf("cozy", "pacing", "session-design", "low-pressure"), listOf("pacing", "theme_message", "scope_structure"), "Making a gentle game with no combat, timers, failure or challenge.", "Many goals exist but none is urgent, and content is rationed over real time: some events occur once per day and shops keep opening hours.", "A relaxed rhythm, and a built-in reason for the player to put the game down.", null, null, "Should your game urge players to keep going, or give them a reason to stop?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-025-warioware-instant-communication", "WarioWare", "00:34:11", "00:35:16", listOf("onboarding", "communication", "short-session", "pacing"), listOf("pacing", "multiplayer", "onboarding", "scope_structure"), "Teaching a game's rules in a moment.", "A rapid series of tiny games, each conveyed through colour, shape, layout and a one-word instruction, so the player must change skills every few seconds.", "Players stay alert and reactive, and it shows how much can be done with a very small idea.", null, null, "Can a player understand what to do within a few seconds, and how would you show it?", listOf("gmtk-015-crazy-taxi-concentrated-loop"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-026-september-12th-serious-game", "September 12th", "00:35:19", "00:36:17", listOf("serious-games", "message", "mechanics-as-argument", "player-interpretation"), listOf("theme_message"), "Using a game to make a point about a serious or political topic.", "The player is told to bomb militants in a village but cannot do so without killing civilians; mourners appear and some villagers become militants, so the only way out is to stop.", "The mechanics themselves lead players to question the approach and to talk about it.", null, null, "Does your game have a point to make, and could its rules carry it?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-027-prince-of-persia-rewind-failure", "Prince of Persia: The Sands of Time", "00:36:19", "00:37:30", listOf("failure", "recovery", "resource-management", "narrative"), listOf("difficulty", "narrative", "simulation_building", "survival_resources"), "Handling failure in both mechanics and story.", "A magic hourglass lets the player rewind time to undo mistakes in hard platforming, and the story is framed as a tale told by the Prince, so deaths read as slips in the telling.", "Recovering from failure becomes a limited resource the player decides when to spend, and the framing gives deaths a reason.", null, null, "What should happen when the player fails, and should recovery be something they spend?", listOf("gmtk-003-rogue-procedural-permadeath"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-028-katamari-visible-growth", "Katamari Damacy", "00:37:34", "00:38:24", listOf("progression", "power-fantasy", "feedback", "visible-growth"), listOf("progression", "game_feel", "theme_message"), "Making the experience of getting stronger feel good.", "The player rolls up ever larger objects, starting with tiny items and ending with huge structures and animals.", "Growth is seen and felt directly; starting small and finishing huge, then looking back, is enjoyable.", null, null, "How could the player see their growth instead of just reading a number?", listOf("gmtk-017-diablo-2-skill-tree-power-fantasy"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-029-devil-may-cry-3-scoring-mastery", "Devil May Cry 3", "00:38:31", "00:39:40", listOf("scoring", "mastery", "depth", "accessibility"), listOf("difficulty", "onboarding", "replayability", "accessibility", "scope_structure"), "Rewarding deep mastery of a complex system without demanding it of everyone.", "A detailed combat system is graded for style from a low rank to a top rank; the top grade requires hard moves, variety and an unbroken combo, while most fights can be passed with basic play.", "Scoring gives engaged players a goal and pushes them to learn the whole system, while others can ignore it.", null, null, "Should depth be optional, and how would the game reward the players who pursue it?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-030-resident-evil-4-varied-pacing", "Resident Evil 4", "00:39:46", "00:41:00", listOf("pacing", "variety", "tension-and-release", "engagement"), listOf("pacing"), "Keeping players engaged without boring or overwhelming them.", "Intense battles alternate with quieter stretches for puzzles, scouting and scavenging, story scenes, shopping and upgrading, and boss encounters, switching before any element becomes stale.", "The player is rarely bored or overloaded, so the game is hard to put down.", null, null, "Which kinds of moments will you alternate, and when should the game change gear?", listOf("gmtk-001-space-invaders-difficulty-curve"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-031-geometry-wars-juice", "Geometry Wars: Retro Evolved", "00:41:16", "00:42:55", listOf("juice", "feedback", "presentation", "game-feel"), listOf("game_feel", "interface", "theme_message"), "Making a familiar mechanic stand out.", "A twin-stick shooter (a polished descendant of an older design) with bright colours, enemies bursting into particles, a bomb that distorts the arena and a driving electronic soundtrack; one stick moves and the other aims.", "The presentation, often called juice, draws the player in as much as the mechanics do.", null, null, "Which moments deserve extra visual and audio feedback?", listOf("gmtk-022-rez-synchronised-audio"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-032-dead-rising-time-limit", "Dead Rising", "00:42:59", "00:44:19", listOf("time-limit", "pressure", "tradeoffs", "risk-management"), listOf("pacing"), "Deciding whether to put a clock on the player.", "A 72-hour countdown runs throughout, so time cannot be wasted, not every character can be rescued, and improving means managing time and learning the mall's layout.", "A constant feeling of being under pressure.", "The video notes that time limits can be a drag, and that in games with one, many players complain or look for ways to remove it.", null, "Would a time limit add the pressure you want, and would some players resent it?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-033-call-of-duty-4-perks-progression", "Call of Duty 4", "00:44:24", "00:45:48", listOf("progression", "multiplayer", "customisation", "unlocks", "balance"), listOf("difficulty", "progression", "multiplayer"), "Giving a competitive shooter a sense of long-term progress.", "Experience from matches unlocks weapons, kill-streak rewards and perks; none is strictly superior, each has drawbacks and counters, and together they allow a loadout matching the player's style; the final reward is resetting to start again.", "Every match moves the player closer to the next unlock, which makes online play compelling.", null, null, "What should each session bring the player closer to?", listOf("gmtk-017-diablo-2-skill-tree-power-fantasy", "gmtk-037-team-fortress-2-counters"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-034-portal-genre-mashup", "Portal", "00:45:58", "00:47:26", listOf("genre-mashup", "puzzle", "approachability", "developer-commentary"), listOf("onboarding", "puzzle_information", "accessibility", "genre_blend"), "Finding a fresh game idea and widening a genre's audience.", "A puzzle game built with shooter tools: free movement in 3D and a portal gun that is aimed like a firearm, plus light combat that rewards outwitting enemies.", "New puzzles around aim, movement and momentum, and an audience of shooter fans who might not otherwise try a puzzle game.", null, null, "Which two genres or toolsets could you combine, and what new problems would that create?", listOf(), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-035-mass-effect-choices-ripple", "Mass Effect", "00:47:30", "00:48:42", listOf("choice-and-consequence", "narrative", "persistence", "branching"), listOf("narrative", "choice", "replayability"), "Making the story respond to what the player decides.", "The player shapes the hero's character and relationships and makes plot choices; in one scene a dispute with a squad member can be talked out or end in a fight that kills him for good, and he is then absent from the sequels.", "Players get distinct personal stories, with consequences that carry across three games.", "The video says the third game could not give a satisfying ending for every possible combination of choices.", null, "Which player choices should have lasting consequences?", listOf("gmtk-048-fallout-new-vegas-side-quests"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-036-skate-realistic-vs-arcade", "Skate (contrasted with Tony Hawk's)", "00:48:53", "00:50:07", listOf("control-scheme", "realism-vs-arcade", "design-angles", "input-design"), listOf("game_feel", "survival_resources", "interface", "scope_structure"), "Approaching the same subject from a different direction.", "Skate favours realism and mimics the physical kick of a board with a stick flick down and up, with complex tricks needing harder stick motions, whereas Tony Hawk's is exaggerated and ignores real physics.", "Two quite different games from one sport, raising the question of what other sports could look like if approached differently.", null, null, "What would a very different take on your subject look like?", listOf("gmtk-020-tony-hawk-feel-on-the-thumbs"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-037-team-fortress-2-counters", "Team Fortress 2", "00:50:10", "00:51:08", listOf("multiplayer", "balance", "counters", "class-design"), listOf("difficulty", "combat", "multiplayer"), "Keeping a complex multiplayer game fair and balanced.", "Nine classes form a web of strengths and weaknesses so that each option has an answer; for example turrets deter fast scouts, grenades destroy turrets, and scouts overwhelm the grenade user.", "The game stays balanced and enjoyable after almost two decades.", null, null, "For each strong option in your game, what counters it?", listOf("gmtk-033-call-of-duty-4-perks-progression"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-038-bioshock-audio-diaries", "BioShock", "00:51:11", "00:52:33", listOf("environmental-storytelling", "narrative", "exploration", "lore"), listOf("exploration", "narrative"), "Telling a story in a world whose inhabitants are gone or mad.", "Recordings made during the city's collapse are scattered around, so the player finds and plays them; they also hold side stories, character background and lore. The video notes the device came from earlier games, but this implementation inspired many others.", "The player assembles the story from what they find, almost like uncovering the past.", null, null, "Could the player discover the story in the world instead of being told it?", listOf("gmtk-065-gone-home-found-objects"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-039-burnout-paradise-open-racing", "Burnout Paradise", "00:52:38", "00:53:59", listOf("open-world", "racing", "freedom", "social-design"), listOf("exploration", "movement", "multiplayer"), "Building an open world that never interrupts play.", "An arcade racer in an open map where the player is always driving; races begin at any junction, leaderboards for each street weave competition into the world, and event rules do not use invisible walls or restrictive fail states, so any route to the destination is allowed.", "Play is continuous: always racing, driving and crashing.", null, null, "Should structured events interrupt free play, or sit inside it?", listOf("gmtk-019-gta-3-missions-and-sandbox"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-040-far-cry-2-friction", "Far Cry 2", "00:54:04", "00:55:06", listOf("friction", "immersion", "fantasy-fit", "quality-of-life"), listOf("survival_resources", "theme_message"), "Deciding whether to remove every irritation or keep some for the sake of the fantasy.", "Weapons corrode and jam, the player has a disease needing regular medicine, the map is a paper held up in real time, and fires can destroy cover.", "The player feels isolated in hostile territory, short of firepower and support.", "The video contrasts this with common practice, where playtesting removes annoyances and quietly helps the player.", null, "Where would friction support your fantasy, and where would it just annoy?", listOf("gmtk-012-resident-evil-scarce-resources"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-041-left-4-dead-ai-director", "Left 4 Dead", "00:55:27", "00:56:50", listOf("dynamic-difficulty", "pacing", "tension-and-release", "adaptive-systems"), listOf("difficulty", "pacing"), "Keeping a game interesting by responding to the players' state.", "A hidden director spawns enemies, tracks each player's intensity from health, incapacitation and time spent fighting, and at a peak starts a quiet phase with no spawns and maybe extra supplies before building tension again.", "Pace and difficulty rise and fall with what the players are doing, instead of being fixed in advance.", null, null, "Should difficulty be fixed ahead of time or respond to how the player is doing?", listOf("gmtk-001-space-invaders-difficulty-curve", "gmtk-007-tetris-two-kinds-of-difficulty"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-042-spelunky-roguelike-platformer", "Spelunky", "00:57:02", "00:58:19", listOf("procedural-generation", "permadeath", "replayability", "genre-mashup"), listOf("difficulty", "replayability", "genre_blend"), "Carrying a genre's core ideas into a different kind of game.", "Rogue's generated levels and permanent death are placed in a platformer, so the player cannot memorise a level and must improve general skills such as jumping, handling enemies, blasting walls and using ropes.", "A fresh take on an old genre that began a wave of roguelikes; the video raises whether progress should persist between runs.", null, null, "Should progress carry over between runs, or should each run start from scratch?", listOf("gmtk-003-rogue-procedural-permadeath"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-043-dead-space-diegetic-interface", "Dead Space", "00:58:39", "00:59:28", listOf("interface", "diegetic-ui", "immersion", "presentation"), listOf("interface", "theme_message"), "Showing information without breaking immersion.", "All interface elements live in the world: health is a meter on the suit's back, ammunition is shown on each weapon, and inventory and shop screens appear as projected holograms.", "A highly immersive horror game, helped by strong sound design and no control-removing cutscenes.", null, null, "Could your interface exist inside your game world?", listOf("gmtk-013-half-life-no-cutscenes"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-044-batman-arkham-asylum-fantasy", "Batman: Arkham Asylum", "00:59:35", "01:00:31", listOf("fantasy-fulfilment", "combat-feel", "stealth", "assisted-input"), listOf("difficulty", "game_feel", "combat", "stealth_horror", "interface", "accessibility", "theme_message"), "Making the player feel like a specific character.", "Combat pulls the hero toward nearby enemies and performs finishing moves automatically, and in stealth the guards are made unlikely to look up or turn round so the hero can stalk them.", "Players get to live out the role of the hero, and the game became the benchmark for superhero adaptations.", null, null, "What fantasy should every decision in your game support?", listOf("gmtk-017-diablo-2-skill-tree-power-fantasy"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-045-plants-vs-zombies-simple-genre-entry", "Plants vs. Zombies", "01:00:38", "01:02:02", listOf("genre-learning", "economy", "unit-roles", "simplicity"), listOf("progression", "combat", "onboarding", "simulation_building", "genre_blend"), "Learning, or teaching, a complex genre.", "A casual tower defence game described as a hidden real-time strategy game: every plant and zombie type has a distinct job, and sunflowers produce the currency to buy more, so players balance offence against economy.", "A clear lesson in unit variety, enemy differentiation and economic balance, accessible to anyone.", null, null, "What is the simplest version of your genre, and what would you keep from it?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-046-fruit-ninja-touch-input", "Fruit Ninja", "01:02:07", "01:03:14", listOf("input-design", "touch", "platform", "hardware"), listOf("game_feel", "interface"), "Designing for a new input method.", "Fruit flies into the air and the player cuts it by swiping a finger across the screen, a game made for touch with no buttons, sticks or d-pad.", "A simple game that stays enjoyable largely through the physical feel of touching the screen.", null, null, "What is the most natural way to interact on the device your players use?", listOf("gmtk-020-tony-hawk-feel-on-the-thumbs"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-047-amnesia-no-combat-horror", "Amnesia: The Dark Descent", "01:03:14", "01:04:12", listOf("horror", "powerlessness", "sanity-mechanic", "no-combat"), listOf("combat", "stealth_horror"), "Pushing player powerlessness further in horror.", "Fighting is removed completely, leaving only running and hiding. A sanity meter drops in darkness and recovers when the player looks at the creatures, so staying composed means staying exposed.", "A genuinely frightening game that influenced both indie and large-studio horror.", null, null, "Would taking away the player's ability to fight make your game stronger?", listOf("gmtk-012-resident-evil-scarce-resources"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-048-fallout-new-vegas-side-quests", "Fallout: New Vegas", "01:04:15", "01:05:09", listOf("quest-design", "choice-and-consequence", "rpg", "multiple-solutions"), listOf("choice", "scope_structure"), "Designing side quests worth playing.", "Quests are varied in tone and can usually be solved several ways: choices that shift karma and faction standing, skill checks that skip steps, outcomes that change with the companion present, and room for the player's own idea.", "Each quest is a small lesson in RPG design, and it strongly influenced another studio's quest design.", null, null, "Should side quests offer more than one way to be solved?", listOf("gmtk-035-mass-effect-choices-ripple", "gmtk-016-deus-ex-player-freedom"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-049-civilization-inverted-pyramid", "Civilization V", "01:05:09", "01:06:35", listOf("onboarding", "complexity-management", "theme", "accessibility"), listOf("onboarding", "simulation_building", "accessibility", "theme_message"), "Making a very large game approachable.", "Following what its designers call an inverted pyramid of decision making, the player first makes a single choice (where to found a city), then two, then dozens per turn, by when they know the rules; the history theme also uses knowledge players already have.", "A big strategy game that is surprisingly easy to start.", null, null, "How many decisions does the player face at the start, and how quickly should that grow?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-050-dark-souls-corpse-run", "Dark Souls", "01:06:40", "01:08:00", listOf("death", "risk-and-reward", "tension", "currency"), listOf("difficulty", "progression", "pacing"), "Making death costly without ending the game.", "When the player dies they drop the souls they carry, which are both experience and money; they must return to the spot to recover them and, if they die first, the souls are lost for good.", "Constant tension: a large stash makes a safe resting point urgent and the trip back dangerous. The video says it popularised this recovery idea, now common.", null, null, "What does the player lose when they die, and can they win it back?", listOf("gmtk-003-rogue-procedural-permadeath", "gmtk-027-prince-of-persia-rewind-failure"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-051-minecraft-player-set-goals", "Minecraft", "01:08:07", "01:09:12", listOf("sandbox", "player-goals", "creativity", "emergent-play"), listOf("emergence"), "Supporting players who prefer to choose their own objectives.", "The game sets no rules or structure; it can be used as a building toy with no enemies, health or hunger, as a survival challenge, or together with others.", "A long-lived game that shows many players enjoy creating and defining their own goals.", null, null, "Should the player choose their own objectives, and what tools would they need?", listOf("gmtk-018-the-sims-player-led-play"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-052-spacechem-open-ended-solutions", "SpaceChem", "01:09:20", "01:10:18", listOf("problem-solving", "replayability", "ownership", "leaderboards"), listOf("multiplayer", "replayability", "puzzle_information"), "Making a puzzle-like game feel personal and worth replaying.", "Instead of a single hidden answer, the player builds an automated factory that converts atoms into molecules and passes if it meets the brief; the result is then compared with other players on three measures.", "Players feel they own their solution, and a below-average comparison motivates them to return and make it faster, smaller or cheaper.", null, null, "Should your challenges have one intended answer, or accept any answer that meets the goal?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-053-skyrim-self-directed-rpg", "Skyrim", "01:10:24", "01:11:15", listOf("rpg", "player-freedom", "exploration", "emergent-story"), listOf("exploration", "narrative", "emergence"), "What makes a role-playing game feel like the player's own adventure.", "A large fantasy world the player explores wherever curiosity leads, with a chosen style such as magic, melee or archery, so the story comes from the places visited, characters met and quests taken.", "The player's story is entirely their own, and the video treats it as a reference point for modern RPGs.", "The video says other RPGs have better quests, stories and customisation.", null, "How much of the story should come from the player's own route and playstyle?", listOf("gmtk-005-zelda-freedom-and-curiosity", "gmtk-016-deus-ex-player-freedom"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-054-journey-wordless-cooperation", "Journey", "01:11:28", "01:12:40", listOf("multiplayer", "cooperation", "communication", "social-design"), listOf("multiplayer"), "Making online play with strangers meaningful rather than transactional or hostile.", "Another anonymous traveller may join for a while; there is no text or voice, no visible names and no way to fight, and the only signal is a button that produces a musical note.", "A surprisingly close bond forms, and some players do not realise it is a real person until the end.", null, null, "If players meet, what limited ways should they have to relate to each other?", listOf("gmtk-010-pokemon-trading-community"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-055-mark-of-the-ninja-shown-information", "Mark of the Ninja", "01:12:49", "01:14:09", listOf("stealth", "information-design", "feedback", "planning"), listOf("game_feel", "stealth_horror", "simulation_building", "puzzle_information"), "How the amount of information shown changes what kind of game it is.", "A side-scrolling stealth game that, unlike its inspiration, displays whether the player is in shadow, how far noises carry, what guards see and intend, and previews the result of each item.", "Stealth becomes planning and strategy instead of patient observation, and the player feels capable.", null, null, "Should the game tell the player how its systems work, or leave them to find out?", listOf("gmtk-014-thief-light-and-sound"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-056-walking-dead-pressured-moral-choices", "The Walking Dead (Telltale)", "01:14:16", "01:15:55", listOf("narrative", "choice-and-consequence", "moral-choices", "time-pressure"), listOf("narrative", "choice", "pacing"), "Making story decisions emotionally heavy.", "Puzzles give way to hard moral choices in a crisis (who is fed, who joins a mission, who is saved); dialogue choices run on a timer, some actions must be taken immediately, and decisions affect later episodes, minor ones being referenced and major ones changing the plot.", "Powerful moments of guilt and regret of a kind only interactive stories produce.", null, null, "Should hard choices be timed, and which should echo later?", listOf("gmtk-035-mass-effect-choices-ripple"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-057-virtues-last-reward-branch-map", "Virtue's Last Reward", "01:15:59", "01:17:02", listOf("branching-narrative", "replayability", "puzzle", "structure"), listOf("narrative", "choice", "replayability", "puzzle_information", "scope_structure"), "Handling branching stories without assuming one playthrough.", "After the story ends the player gets a flowchart of how decisions led to each ending and can re-enter at any point to choose differently, carrying information such as a password or a secret between timelines.", "Branching becomes part of the gameplay, unlocking more endings through knowledge gathered across paths.", null, null, "If your story branches, should players be able to move between branches?", listOf("gmtk-035-mass-effect-choices-ripple"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-058-xcom-output-randomness", "XCOM: Enemy Unknown", "01:17:13", "01:18:41", listOf("randomness", "strategy", "risk", "player-trust"), listOf("choice", "combat", "replayability"), "How random outcomes affect a player who has planned carefully.", "Each shot shows a hit percentage based on sight lines and distance, and the outcome is then left to chance; the displayed odds are adjusted because people misjudge probability, so an 80% shown may be about 90% in the code.", "It can create memorable moments but more often disappoints, since a sound plan fails on one bad roll; the designer removed the feature in a later game.", "The video says the sting of a failed roll tends to outweigh the thrill, and that the designer regretted the feature.", null, "Should luck be resolved before the player acts or after, and how will failures feel?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-059-spec-ops-choices-through-play", "Spec Ops: The Line", "01:18:45", "01:19:46", listOf("choice", "narrative", "immersion", "interface"), listOf("narrative", "choice", "interface", "theme_message"), "Presenting a choice without a menu.", "Difficult decisions are posed through the game's normal actions, for example aiming at one of two captives, which also allows unlisted options such as shooting neither or shooting the snipers.", "More immersive and natural than choosing between two labelled buttons.", null, null, "Could a choice be made by playing instead of by picking from a menu?", listOf("gmtk-056-walking-dead-pressured-moral-choices"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-060-spaceteam-local-cooperation", "Spaceteam", "01:19:55", "01:20:48", listOf("multiplayer", "local-play", "cooperation", "communication"), listOf("multiplayer"), "Building a game around people sharing a room.", "Each player has a different control panel and gets instructions that mostly concern other people's panels, so they must call out orders and listen for those meant for them.", "Plenty of noise and enjoyment, showing the benefit of designing for shared-space play.", null, null, "Is your game best played in the same room, and what would that change?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-061-dishonored-world-reacts", "Dishonored", "01:20:54", "01:22:08", listOf("player-expression", "consequence", "world-state", "morality-systems"), listOf("choice", "emergence"), "Making the world respond to a playstyle without labelling it good or bad.", "The player may be a stealthy unseen killer or a chaotic one, with a non-lethal route for every target; the game never judges, but disorder shows in the city (swarms of rats at high levels) and in characters who may refuse help or turn hostile.", "A subtler alternative to a karma meter that makes players weigh actions without feeling mechanical.", null, null, "How should the world change to reflect how the player plays, without scoring them?", listOf("gmtk-016-deus-ex-player-freedom"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-062-stanley-parable-play-with-conventions", "The Stanley Parable", "01:22:13", "01:23:13", listOf("meta-design", "satire", "player-choice", "narration"), listOf("narrative", "choice", "theme_message", "scope_structure"), "Getting players to think about the conventions of games themselves.", "An unreliable narrator, breaks of the fourth wall and jokes at the player's expense comment on player choice and narrative convention.", "Players laugh, then reflect on how games steer decisions and emotions; the creator also hoped to prompt discussion afterwards.", null, null, "Is there a convention in your genre worth poking at?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-063-brothers-story-in-the-controller", "Brothers: A Tale of Two Sons", "01:23:20", "01:24:29", listOf("controls", "narrative", "cooperation", "game-feel"), listOf("narrative", "game_feel", "multiplayer", "interface"), "Telling a story through the controls themselves.", "The player steers both brothers simultaneously, each assigned a stick and a set of shoulder buttons, solving puzzles that normally need two players.", "The two characters come to feel tied to the player's two thumbs, so the most affecting storytelling occurs in the hands.", null, null, "Could the way the player holds or uses the controls carry part of the story?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-064-clicker-games-incremental-progress", "Cow Clicker and Cookie Clicker", "01:24:38", "01:26:10", listOf("incremental", "progression", "optimisation", "idle-games"), listOf("progression", "simulation_building"), "Why very simple increment-a-number games can hold players.", "A parody game gave each player one cow to click on a six-hour cooldown to raise a counter; a follow-up adds upgrades and unlocks that speed up the clicking or automate it.", "The video presents them as a pure form of how players get absorbed by upgrades, progression, rewards and optimising, whatever one thinks of them.", null, null, "Which parts of upgrade-and-optimise loops do you want, and how much should they carry your game?", listOf("gmtk-067-steamworld-dig-upgrade-loop"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-065-gone-home-found-objects", "Gone Home", "01:26:14", "01:27:31", listOf("environmental-storytelling", "narrative", "exploration", "player-inference"), listOf("exploration", "narrative", "puzzle_information"), "Building a whole game from exploring a place and its objects.", "The player searches an abandoned family home, reading notes, receipts, cards and other items, finding them in a partly random order or missing some.", "The player fills gaps and draws connections, so understanding feels personal and hard won; narrative placed in the level alone can sustain a game.", null, null, "Could the player piece the story together from objects and places?", listOf("gmtk-038-bioshock-audio-diaries"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-066-papers-please-empathy-through-rules", "Papers, Please", "01:27:36", "01:28:47", listOf("empathy", "moral-choice", "rules-as-narrative", "deduction"), listOf("narrative", "choice", "puzzle_information", "theme_message"), "Helping the player understand why people make hard choices.", "The player is a border inspector checking papers, first as a spot-the-error deduction task, then facing people whose documents are incomplete and choosing between the rules and their fate, with penalties for admitting them.", "The game shows why people decide as they do by placing the player in the position and asking what they would do.", null, null, "Could a routine task become the setting for a hard decision?", listOf("gmtk-056-walking-dead-pressured-moral-choices"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-067-steamworld-dig-upgrade-loop", "SteamWorld Dig", "01:28:47", "01:30:10", listOf("core-loop", "progression", "upgrades", "pacing"), listOf("progression", "pacing", "scope_structure"), "Building a satisfying dig, return and upgrade loop.", "The player begins with weak tools, a dim light and room for a few lumps of ore, returns to the surface to sell and upgrade, then digs somewhat deeper each trip.", "A very compelling cycle of wanting to go just a little further.", "The video warns the loop can be shallow padding in the wrong hands; this game avoids that with variety, a story and secrets.", null, "Does your repeating loop have enough variety around it to stay meaningful?", listOf("gmtk-064-clicker-games-incremental-progress", "gmtk-017-diablo-2-skill-tree-power-fantasy"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-068-alien-isolation-one-good-ai", "Alien: Isolation", "01:30:15", "01:31:33", listOf("ai", "horror", "unpredictability", "enemy-design"), listOf("emergence", "combat", "stealth_horror"), "Getting believable AI without building many characters.", "A single stalking enemy is driven by systems for sight, hearing, sneaking up and reacting to fire; its movements are rarely scripted and it gains new abilities over time.", "It behaves differently each run and seems to learn from the player, so it stays frightening even after many restarts.", null, null, "Would one well-built opponent serve you better than many simple ones?", listOf("gmtk-072-metal-gear-solid-v-adaptive-ai"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-069-mario-kart-catch-up-items", "Mario Kart", "01:31:36", "01:32:48", listOf("balance", "negative-feedback-loop", "multiplayer", "skill-gap"), listOf("difficulty", "game_feel", "multiplayer"), "Keeping a game enjoyable for players of different skill together.", "Item boxes give results based on race position: leaders receive weak items and trailing players get strong ones, including a missile that hunts the leader.", "A self-balancing negative feedback loop: struggling players get a boost and strong players are slowed, so everyone can have fun.", null, null, "Should your game help players who are behind, and how visibly?", listOf("gmtk-037-team-fortress-2-counters"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-070-80-days-text-as-technology", "80 Days", "01:32:56", "01:34:26", listOf("interactive-fiction", "scope", "replayability", "narrative"), listOf("narrative", "replayability", "scope_structure"), "Delivering a very large game on a small production budget.", "A text-based take on a round-the-world journey in which a paragraph can introduce a city or character that would otherwise need models, textures, AI and voice acting; one playthrough shows only a small share of the text.", "A big game that encourages replays with different routes and decisions, with branching on a scale the video says exceeds the others mentioned.", null, null, "Would text carry part of your content more cheaply than art or voice?", listOf("gmtk-057-virtues-last-reward-branch-map"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-071-her-story-withheld-information", "Her Story", "01:34:30", "01:35:50", listOf("information-design", "narrative", "search", "deduction"), listOf("narrative", "puzzle_information"), "Making uncovering a story the gameplay.", "Interview footage is divided into nearly 300 short clips in an old-style database searched by typing words, so the player finds clips from what they hear and assembles the story from out-of-order evidence.", "The player pieces events together like an investigator, and withholding information keeps play engaging.", null, null, "What information could you withhold so that finding it is the game?", listOf("gmtk-065-gone-home-found-objects"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-072-metal-gear-solid-v-adaptive-ai", "Metal Gear Solid V: The Phantom Pain", "01:36:09", "01:37:32", listOf("adaptive-systems", "ai", "systemic-design", "player-habits"), listOf("difficulty", "emergence"), "Stopping players from repeating one optimal strategy.", "The enemy AI adapts to habits, for instance adding helmets if the player keeps aiming at heads or floodlights if bases are always raided at night; enemy camps hold autonomous agents that can be fooled, lured out and trapped.", "Players cannot reuse the same best tactic and are pushed to vary their approach.", null, null, "If players find a dominant tactic, how should the game respond?", listOf("gmtk-068-alien-isolation-one-good-ai", "gmtk-041-left-4-dead-ai-director"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-073-metal-gear-solid-v-fun-failure", "Metal Gear Solid V: The Phantom Pain", "01:36:09", "01:36:58", listOf("failure", "pacing", "stealth", "player-choice"), listOf("difficulty", "choice", "pacing", "stealth_horror"), "Making a failed attempt enjoyable.", "When stealth breaks down, play shifts from slow sneaking to a frantic action sequence with explosions and rescue helicopters; an extraction mechanic lets the player choose whether to kill or recruit soldiers, and scoring allows any style while rewarding speed and stealth.", "Failure becomes a different kind of fun, and the player decides how to play.", null, null, "What does failing look like in your game, and can it be interesting?", listOf("gmtk-027-prince-of-persia-rewind-failure"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-074-undertale-spare-or-defeat", "Undertale", "01:37:38", "01:39:00", listOf("morality", "choice", "replayability", "combat-alternatives"), listOf("choice", "combat", "replayability"), "Making the player confront what they do to enemies.", "Each enemy can be defeated or spared by talking, flattering, listening or simply waiting; the story and endings differ by approach, and on a later playthrough the game comments on the earlier choices.", "Players may try to spare everyone or take a destructive route, and the game asks whether a new save should undo the harm.", null, null, "Does every enemy need to be fought, and what other outcomes could there be?", listOf("gmtk-047-amnesia-no-combat-horror"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-075-downwell-dual-purpose-mechanics", "Downwell", "01:39:04", "01:39:38", listOf("mechanics-economy", "depth", "interface", "minimalism"), listOf("progression", "simulation_building", "interface", "scope_structure"), "Getting depth from few mechanics.", "The jump button doubles as fire in mid-air; firing destroys enemies and blocks and slows the fall, kills refill ammunition and build a combo, and landing resets both.", "Considerable depth from half as many mechanics.", null, null, "Which of your mechanics could do two jobs?", listOf("gmtk-021-ico-design-by-subtraction"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-076-downwell-risk-and-reward-curve", "Downwell", "01:39:38", "01:40:05", listOf("risk-and-reward", "difficulty-curve", "skill-ceiling", "scoring"), listOf("difficulty", "replayability"), "Serving new and expert players in the same game.", "Stomping on enemies gives the largest rewards but is riskier than shooting them, so it suits experienced players.", "Newcomers shoot and aim to survive while experts move on to stomping and playing for score, creating a self-selected difficulty curve.", null, null, "Is there a riskier way to play that rewards experts more, and is it optional?", listOf("gmtk-029-devil-may-cry-3-scoring-mastery"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-077-yakuza-0-place-as-character", "Yakuza 0", "01:40:09", "01:41:29", listOf("setting", "immersion", "side-activities", "world-building"), listOf("exploration", "simulation_building", "theme_message", "scope_structure"), "Making a believable place the centre of a game.", "A detailed fictional district assembled from realistic stores, vending machines and architecture, with familiar goods to buy and activities such as darts, karaoke, hostess bars and arcades that make the player feel like a regular; the district recurs across the series.", "The city functions almost like a character, and returning to see what changed is rewarding.", null, null, "What small activities and details would make your setting feel lived in?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-078-kerbal-space-program-physics-comedy", "Kerbal Space Program", "01:41:34", "01:42:31", listOf("physics", "building", "humour", "clear-goal"), listOf("emergence", "onboarding", "simulation_building", "theme_message"), "Using unpredictable physics in a game.", "The player builds rockets aiming to reach space, with a clear target of getting a craft very high without it exploding or spinning out of control.", "Physics resists designer control but is nearly always funny: a carefully built craft falling apart is entertaining, even in a game praised for realism.", "The video notes that designers usually want control, and physics is unpredictable.", null, "Would physics-driven outcomes add fun to your game, and can you live with their unpredictability?", listOf("gmtk-051-minecraft-player-set-goals"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-079-super-mario-maker-learn-by-making", "Super Mario Maker", "01:42:54", "01:43:34", listOf("level-design", "learning", "creation-tools", "playtesting"), listOf("emergence", "onboarding", "scope_structure"), "Learning design by starting from familiar parts.", "Players assemble levels from the rules, tools and visuals of the Mario platformers, play others' levels and look for tips.", "They find that making something fun is difficult, and so get a first experience of level design.", "The video says the original's online servers are closed, so sharing there is no longer possible.", null, "Would letting players build with your rules be valuable, and how would you teach them?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-080-doom-2016-glory-kill", "Doom (2016)", "01:43:34", "01:44:45", listOf("fantasy-fulfilment", "health-systems", "aggression", "game-feel"), listOf("game_feel", "combat", "theme_message"), "Making every design decision serve one central fantasy.", "Health does not regenerate behind cover; instead the player staggers demons and rushes in for a brutal finishing move that drops health pickups.", "The player feels aggressive and forward-driving, since the loop pushes them toward enemies where most shooters reward retreat, and the move recurs constantly because it supplies a key resource.", null, null, "What should the player's main resource loop make them do, and how does it fit the fantasy?", listOf("gmtk-044-batman-arkham-asylum-fantasy", "gmtk-008-doom-speed-and-space"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-081-factorio-joy-of-automation", "Factorio", "01:44:49", "01:45:42", listOf("automation", "factory-building", "problem-solving", "optimisation"), listOf("simulation_building", "puzzle_information"), "What makes building automated production satisfying.", "After a crash landing the player builds a self-running factory that mines, smelts and manufactures, growing into a planet-wide web of production lines linked by trains and drones; the video likens it to SpaceChem but larger and more open.", "Players can disappear into it for hundreds of hours, absorbed in solving problems and squeezing out efficiency.", null, null, "Is the player's main satisfaction building systems that run themselves?", listOf("gmtk-052-spacechem-open-ended-solutions"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-082-persona-5-genre-alternation", "Persona 5", "01:45:46", "01:46:56", listOf("pacing", "genre-blending", "structure", "theme"), listOf("pacing", "genre_blend", "theme_message", "scope_structure"), "Alternating two very different kinds of gameplay without disorienting players.", "A school life simulation (classes, part-time jobs, dates) alternates with a dungeon-crawling RPG, and the same characters are friends in the social half and party members in the fighting half.", "Switching helps pacing, and a shared central theme keeps the halves connected.", "The video warns that if a player prefers one half or stays too long in one, switching to the other can feel irritating or disruptive.", null, "If your game has two modes, what ties them together?", listOf("gmtk-030-resident-evil-4-varied-pacing"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-083-hitman-mastery-through-repetition", "Hitman", "01:47:01", "01:48:31", listOf("mastery", "replayability", "level-design", "learning-by-repetition"), listOf("difficulty", "onboarding", "replayability", "scope_structure"), "Making repeated attempts at a level worthwhile.", "Levels run on a fixed routine: events happen at the same times, targets follow looping routes and objects appear in the same places; first attempts usually go wrong and the player tries again.", "Each replay adds knowledge and moves the player toward flawless execution; repetition can lead to a real sense of mastery.", null, null, "Should levels be predictable enough for players to master through repetition?", listOf("gmtk-042-spelunky-roguelike-platformer"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-084-overcooked-forced-cooperation", "Overcooked", "01:48:38", "01:49:49", listOf("cooperation", "multiplayer", "communication", "emergent-chaos"), listOf("emergence", "multiplayer"), "Making a co-op game genuinely require cooperation.", "Up to four players run a kitchen; the obvious plan of one fixed job each breaks down because dirty plates arrive at an awkward rate that nobody wants to own, forcing swaps, shouting and warnings.", "A chaotic, loud and enjoyable game and a model of well-designed co-op.", null, null, "What will force your players to coordinate rather than work in parallel?", listOf("gmtk-060-spaceteam-local-cooperation"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-085-furi-teaches-patience", "Furi", "01:49:53", "01:50:54", listOf("combat-design", "boss-fights", "skill-teaching", "patience"), listOf("difficulty", "combat", "onboarding"), "Using combat to teach careful play.", "A boss-rush game in which the player dodges patterns, waits for a gap, attacks briefly and retreats; pressing the attack button repeatedly fails, and each boss is a long lesson that must be passed before moving on.", "Players learn patience and observation; the narrator found the skill transferred to another game.", null, null, "What habit should your combat teach, and what makes the wrong habit fail?", listOf("gmtk-050-dark-souls-corpse-run"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-086-breath-of-the-wild-player-directed-quest", "The Legend of Zelda: Breath of the Wild", "01:50:59", "01:52:28", listOf("player-freedom", "open-world", "structure", "exploration"), listOf("exploration", "scope_structure"), "Giving an open world a goal without imposing an order.", "After a short tutorial the player may go anywhere and may confront the final boss at once, though they will almost surely lose; exploring finds gear, each cleared dungeon weakens the boss and some quest lines give items for the assault.", "The whole game turns into a player-directed preparation for a showdown, which supports a sense of adventure, discovery and surprise.", "The video contrasts it with later series entries that followed a stricter, more linear structure.", null, "Could one clear goal let players choose their own path toward it?", listOf("gmtk-005-zelda-freedom-and-curiosity", "gmtk-009-super-metroid-explore-and-unlock"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-087-fortnite-constant-reinvention", "Fortnite", "01:52:33", "01:53:35", listOf("live-service", "content-updates", "adaptation", "retention"), listOf("difficulty", "replayability"), "Keeping a long-running game feeling fresh.", "The developers repeatedly reconsider key mechanics (building became optional), and each season of a few months adds weapons, vehicles, movement options and characters, and has remade the map several times.", "Returning after a break feels like a different game.", "The video says this rate of reinvention is probably unsustainable for most studios, and perhaps for the developer itself.", null, "Will your game change over time, and can you afford to keep changing it?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-088-getting-over-it-earned-success", "Getting Over It with Bennett Foddy", "01:53:38", "01:54:49", listOf("difficulty", "punishment", "control-scheme", "earned-success"), listOf("difficulty", "game_feel", "interface"), "Making success feel earned through harsh failure.", "A single continuous mountain with no checkpoints or save points, climbed using awkward, unconventional mouse motions, where a slip can send the player back to the bottom; the only support is a philosophical narration.", "Failure hurts, which makes any progress feel earned.", null, "Players who dislike heavy punishment may quit; the video frames it as a deliberate throwback and does not recommend it for everyone.", "How harshly should failure be punished, and who is your audience for that?", listOf("gmtk-003-rogue-procedural-permadeath", "gmtk-050-dark-souls-corpse-run"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-089-shadow-of-war-nemesis-system", "Middle-earth: Shadow of War", "01:54:53", "01:56:14", listOf("emergent-narrative", "procedural-characters", "memory", "enemy-design"), listOf("narrative", "emergence", "combat", "replayability", "puzzle_information"), "Generating memorable personal stories in a large game.", "Orc captains are randomly created with a name, voice, skills and a record of past encounters with the player, so one the player ran from may taunt them later and one that was burned may return scarred and seeking revenge.", "Stories unique to each player, driven by which orcs appear and how they react.", null, null, "Should recurring enemies remember what the player did to them?", listOf("gmtk-068-alien-isolation-one-good-ai"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-090-among-us-social-deduction", "Among Us", "01:56:19", "01:57:18", listOf("social-deduction", "multiplayer", "deception", "party-games"), listOf("multiplayer", "puzzle_information"), "Building a game around deception between players.", "Most players do tasks to keep a ship running while a few secret impostors sabotage and eliminate; anyone can call a meeting to accuse, a vote follows and the outcome is revealed immediately.", "It encourages social behaviour rarely used in daily life, and because it centres on the people, it stays enjoyable for a very long time.", null, null, "Would a hidden-role mechanic suit the people who will play together?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-091-celeste-grace-mechanics-and-assist", "Celeste", "01:57:23", "01:58:46", listOf("accessibility", "game-feel", "difficulty", "assist-mode"), listOf("difficulty", "game_feel", "onboarding", "accessibility"), "Making a hard game kind to the player.", "Movement code is full of small forgiving rules (for example coyote time, allowing a jump just after leaving a ledge), and an assist mode provides accessibility options and outright cheats, introduced with an explanation of the game's intent.", "The game feels responsive and never punitive while staying demanding; most players do not need assist mode unless they have to.", null, null, "Which forgiving details and assist options would help players without changing the challenge you intend?", listOf(), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-092-rimworld-story-generator", "RimWorld", "01:58:49", "01:59:37", listOf("emergent-narrative", "simulation", "event-director", "systemic-design"), listOf("narrative", "emergence", "pacing", "simulation_building"), "Making a game that generates and curates stories.", "Many interacting systems create unexpected effects, and an AI storyteller monitors the colony's state and selects events according to which would be the most engaging.", "Distinctive personal story moments from a survival colony-management game.", null, null, "Should something select the events that happen, and by what measure?", listOf("gmtk-041-left-4-dead-ai-director", "gmtk-018-the-sims-player-led-play"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-093-florence-interaction-as-metaphor", "Florence", "01:59:42", "02:00:50", listOf("narrative", "interaction-metaphor", "mini-games", "emotion"), listOf("narrative", "game_feel", "genre_blend", "theme_message"), "Conveying feelings through the way the player interacts.", "A love story told through brief mini games with simple touch controls, where actions work as metaphors (scraping to reveal a dream, pushing a character across the screen) and speech bubbles built from puzzle pieces show how well two people communicate.", "The emotion comes from what the player does rather than from the visuals.", null, null, "What small interactions could express how a moment feels?", listOf("gmtk-063-brothers-story-in-the-controller"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-094-into-the-breach-shown-intentions", "Into the Breach", "02:00:55", "02:01:54", listOf("information-design", "tactics", "randomness", "puzzle"), listOf("combat", "replayability", "puzzle_information"), "What happens when a strategy game hides nothing about the enemy's next move.", "Enemies reveal exactly what they will do next turn, so the player can kill them first, step aside, or push one enemy into another's attack.", "The game becomes an elegant puzzle about turning enemies against each other, with luck almost removed and nearly everything visible.", null, null, "Should the player know what the opponent will do next?", listOf("gmtk-058-xcom-output-randomness", "gmtk-055-mark-of-the-ninja-shown-information"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-095-slay-the-spire-synergy", "Slay the Spire", "02:02:00", "02:03:04", listOf("synergy", "deck-building", "roguelike", "build-crafting"), listOf("progression", "replayability", "simulation_building", "survival_resources"), "Making the combination of options into a build feel great.", "Cards are added to a deck over time, and some work together (one applies poison, another hits poisoned enemies harder); the player shapes a deck and passive relics around a plan.", "A deck that delivers huge combined damage feels overwhelmingly powerful; this is safe in a roguelike because randomness means a given card or relic can never be guaranteed.", null, null, "Which options should combine, and what stops one combination from always being available?", listOf("gmtk-017-diablo-2-skill-tree-power-fantasy", "gmtk-096b-vampire-survivors-distilled-loop"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-096-disco-elysium-micro-reactivity", "Disco Elysium", "02:03:08", "02:04:26", listOf("choice-and-consequence", "narrative", "reactivity", "rpg"), listOf("narrative", "choice"), "How small choices can matter without branching endings.", "A combat-free RPG in which everyone follows largely the same story, yet the game tracks and refers to small player behaviour (running everywhere, being rude, walking about in underwear), with a late scene where characters reflect on the player's actions.", "Small choices become memorable; the game's writer calls this micro-reactivity, a game that notices and responds to small player behaviour.", null, null, "Could the game notice small things the player does, instead of only large branches?", listOf("gmtk-035-mass-effect-choices-ripple", "gmtk-061-dishonored-world-reacts"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-097-outer-wilds-knowledge-as-progress", "Outer Wilds", "02:04:31", "02:05:37", listOf("exploration", "information-game", "progression", "discovery"), listOf("exploration", "progression", "puzzle_information"), "Gating progress by knowledge instead of abilities.", "In a simulated solar system with a time loop, progress is blocked not by fights or ability unlocks but by what the player understands; each planet holds clues that open areas on others.", "A rewarding cycle of exploring and learning; the designer wanted a world that keeps pointing to things players can go and discover.", null, null, "Could what the player knows, rather than what they own, open the next area?", listOf("gmtk-071-her-story-withheld-information", "gmtk-009-super-metroid-explore-and-unlock"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-098-half-life-alyx-vr-hands", "Half-Life: Alyx", "02:05:42", "02:06:53", listOf("vr", "input-design", "emergent-play", "interaction"), listOf("emergence", "game_feel", "interface"), "What new kinds of play come from tracked hand controllers.", "Controllers that follow hands and fingers let the player crack a door open slightly and fire through it, fumble a reload and spill bullets, or grab an object to knock an enemy away.", "Emergent play that is not a designed mechanic in the usual sense but a natural result of freeform interaction.", "It needs a VR headset, as the video notes.", null, "What does your input device allow that a standard controller would not?", listOf("gmtk-046-fruit-ninja-touch-input"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-099-inscryption-layered-surprise", "Inscryption", "02:06:59", "02:07:52", listOf("mystery", "meta-narrative", "surprise", "genre-mixing"), listOf("narrative", "puzzle_information", "genre_blend"), "Keeping a game surprising throughout.", "A deck-building card battler that blends several genres, visual styles and storytelling methods, moves between the game and a fictional world around it, and places its deepest lore in an alternate reality game outside the game.", "Players believe they have reached the end and discover they have barely begun.", null, null, "What could the player discover late that changes how they see the game?", listOf(), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-096b-vampire-survivors-distilled-loop", "Vampire Survivors", "02:07:56", "02:09:04", listOf("core-loop", "progression", "synergy", "engagement"), listOf("progression", "scope_structure"), "How far a levelling loop can be simplified and still hold players.", "The character attacks automatically so the player only moves near enemies and waits; kills give experience to buy new or stronger attacks, and some attacks strengthen each other.", "Despite minimal input it is very hard to put down, combining the strongest elements of several earlier games; the video leaves open whether that is good.", null, null, "Which part of a levelling loop is the pleasure, and what could you remove around it?", listOf("gmtk-017-diablo-2-skill-tree-power-fantasy", "gmtk-064-clicker-games-incremental-progress", "gmtk-095-slay-the-spire-synergy"), "high", pilot = true, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-100-tunic-secrets-in-plain-sight", "Tunic", "02:09:08", "02:10:06", listOf("secrets", "discovery", "optional-depth", "player-curiosity"), listOf("exploration", "puzzle_information", "scope_structure"), "Making secrets satisfying to find.", "Most puzzles use things already visible in the world whose meaning the player has not yet grasped; later, often through pages of an in-game manual, they suddenly make sense; the secrets are never forced and can be ignored.", "A burst of excitement and understanding when a secret clicks, and a pull toward working it out personally instead of reading about it.", null, null, "Which secrets could be hidden in plain sight and left entirely optional?", listOf("gmtk-071-her-story-withheld-information"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("gmtk-101-shadows-of-doubt-procedural-city", "Shadows of Doubt", "02:10:10", "02:11:25", listOf("procedural-generation", "simulation", "detective", "emergent-narrative"), listOf("narrative", "emergence", "replayability", "simulation_building", "puzzle_information"), "What procedural generation can do beyond levels.", "A city block with hundreds of randomly generated residents, each with a job, home, partner, blood type, fingerprints, schedule and motives, one of whom decides to commit a murder; the player follows clues and arranges notes on a pinboard.", "A complex system that yields endless murders and cases, with stories that feel personal to each detective; the game is still in early access.", "The video adds that games need not be full of complex systems; simplicity and elegance are strengths of other games on the list.", null, "What would you generate instead of hand-authoring, and what would the player do with it?", listOf("gmtk-003-rogue-procedural-permadeath", "gmtk-089-shadow-of-war-nemesis-system"), "high", pilot = false, sourceId = "gmtk", classification = "SOURCE_SUPPORTED", explicitOnly = false),
        KnowledgeEntry("karh-001-climb", "CLIMB (vitality structure)", "Analysis: CLIMB", "", listOf("effort-driven-advancement", "ranking", "level-systems"), listOf("engagement_loops"), "Naming the feeling of moving upward through effort the player put in, as opposed to drifting forward on their own.", "Ranked ladders and level-up systems are the typical designs behind it. Competitive ranks in several multiplayer titles climb in slow, multi-hour steps, while role-playing games tie it to raising a character or its equipment.", "The player senses an upward push they caused themselves (making it up the ladder), which the author separates from plain forward progress such as story advancement.", "The paper offers this as a hypothesis from one author's play history. It links the experience to problem gaming only as something to test, and does not show that ladders cause it. Ranking and level systems can also frustrate players who stall.", "Bob's reading: if a design needs a sense of earned advancement, ask whether a visible ladder or level track fits the fantasy. Wanting this feeling is not a decision to add ranks or levels.", "If this feeling appeals, what would 'moving up' mean in your game, and what would the player do to earn it?", listOf("karh-004-chronotope-scale", "karh-005-meta-spatial", "karh-006-meta-temporal", "karh-002-final-stretch"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_CONSTRUCT", explicitOnly = true),
        KnowledgeEntry("karh-002-final-stretch", "FINAL STRETCH (vitality structure)", "Analysis: FINAL STRETCH", "", listOf("near-completion", "goal-gradient", "milestones"), listOf("engagement_loops"), "Naming the pull a player feels when a goal is nearly done and finishing looks small and sensible.", "Daily reward meters that sit just short of a threshold, level or rank bars close to filling, and progress sliced into small milestones all create it. In competitive mobile titles, nested targets let the feeling recur at several scales within one session.", "The player feels drawn to close the gap, with the sense that finishing is both possible and reasonable. The paper says it points toward the present or future and has no meaningful past form once the gap is closed.", "The same pull can stretch sessions beyond what a player intended, and the paper discusses it alongside problem gaming as a hypothesis, not a proven cause. Using it to hold attention conflicts with a calm, respectful design.", "Bob's reading: milestones that mark real accomplishment can give healthy closure points. Meters engineered to stay just out of reach are a retention tactic and should only be chosen deliberately.", "Where in your game should a player reach a natural stopping point, and should the game make stopping easy there?", listOf("karh-001-climb", "karh-006-meta-temporal", "karh-007-design-experience-bond"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_CONSTRUCT", explicitOnly = true),
        KnowledgeEntry("karh-003-alert", "ALERT (vitality structure)", "Analysis: ALERT", "", listOf("attention-signals", "notifications", "signal-cues"), listOf("engagement_loops"), "Naming the quick jolt of attention when a player notices a signal that offers instantly accessible information.", "Blinking level-up indicators, highlighted reward buttons, sound cues for invitations and red marks on a home screen all trigger it. It is always a brief moment, and the player may act on it now or postpone it.", "The player feels a short pull to look and settle the uncertainty. Most uses the paper describes simply tell players what they can do; stacking many signals on one screen turns it into constant interruption.", "Presented as a hypothesis from one author's play history. Too many signals feel excessive or stressful, and frequent short returns can add up to a large share of play time. In the games analysed, the author found it less central to serious gaming problems than the other two.", "Bob's reading: signals earn their place when they communicate something the player wants to know. This does not authorise notifications, daily prompts, or purchase nudges.", "Which moments in your game does the player truly need to be told about, and how should the game stay quiet the rest of the time?", listOf("karh-004-chronotope-scale", "karh-006-meta-temporal", "karh-007-design-experience-bond"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_CONSTRUCT", explicitOnly = true),
        KnowledgeEntry("karh-004-chronotope-scale", "Micro, meso and macro time scales", "Analysis", "", listOf("experience-time-scale", "feeling-scale"), listOf("engagement_loops"), "Describing how long or large an experienced feeling is, so the same feeling can be compared across designs.", "The paper places a feeling on a continuum: macro is slow and drawn out (a rank that takes weeks), meso is faster and sharper (a ladder that resets monthly), and micro is immediate (a signal that lands in the moment). One construct may appear at more than one scale.", "It gives designers a vocabulary for asking how fast a reward or goal should be felt, instead of only asking whether it exists.", "The scales are loose points on a continuum, not measured categories, and the author notes his wording cannot fully convey the intended feeling.", "Bob's reading: when discussing pacing, it can help to say whether a goal is meant to be felt within a moment, a session or a season.", "Should the main goals in your game be felt within a moment, within one session, or over many sessions?", listOf("karh-001-climb", "karh-003-alert", "karh-005-meta-spatial"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_FRAMEWORK", explicitOnly = true),
        KnowledgeEntry("karh-005-meta-spatial", "Self, avatar or object perspective", "Analysis", "", listOf("perspective-distance", "avatar-identification"), listOf("engagement_loops"), "Describing whether a feeling is attached to the player, to their character, or to something the character owns.", "The paper's example is advancement: a rank belongs to the player themselves, a character level belongs to the avatar a step away, and upgrading a weapon sits even further out on an object.", "The same structure of feeling stays recognisable, but it feels closer or more distant depending on what carries it.", "This is a descriptive lens from the author's own examples, not a tested prediction of how strongly players respond.", "Bob's reading: choosing whether progress belongs to the player, the character or the gear changes how personal it feels, which can matter for tone.", "Should progress in your game belong to the player, to their character, or to their equipment?", listOf("karh-001-climb", "karh-004-chronotope-scale", "karh-006-meta-temporal"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_FRAMEWORK", explicitOnly = true),
        KnowledgeEntry("karh-006-meta-temporal", "Past, present and future perspective", "Analysis", "", listOf("temporal-perspective", "anticipation"), listOf("engagement_loops"), "Describing whether a feeling looks back at something done, sits in the action itself, or anticipates something ahead.", "Advancement can be felt in all three ways: looking down at the distance covered, taking the step now, or looking up at what is next. The paper says the near-completion pull has no past form, and the attention jolt is restricted to the moment with no past form.", "It helps separate satisfaction in hindsight from anticipation and from the immediate action.", "The author uses these as working descriptions and says they await empirical refinement.", "Bob's reading: a design can deliberately favour reflection, action or anticipation; mixing them without intent can blur what the player feels.", "Do you want players mainly to enjoy looking back at what they achieved, the action itself, or what comes next?", listOf("karh-001-climb", "karh-002-final-stretch", "karh-003-alert", "karh-005-meta-spatial"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_FRAMEWORK", explicitOnly = true),
        KnowledgeEntry("karh-007-design-experience-bond", "Design and experience as a pair", "Vitality Structures", "", listOf("design-experience-pairing", "player-variation"), listOf("engagement_loops"), "Avoiding the assumption that a design feature always produces one particular feeling.", "The paper treats a construct as the pairing of a specific design with a specific experience. Either side can occur without the other: a player may use a ranking screen without feeling any ascent, and may feel ascent in life outside games.", "It reminds designers that players may react to the same feature in different ways, so the intended feeling needs checking with real players.", "The paper presents this as a conceptual proposal. It explicitly calls for later empirical studies to test it and gives no measured effect sizes.", "Bob's reading: when borrowing a mechanic from another game, plan to observe how your own players feel instead of assuming the same result.", "What feeling do you want a given feature to create, and how will you find out whether players actually feel it?", listOf("karh-002-final-stretch", "karh-003-alert", "karh-008-source-limits"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_FRAMEWORK", explicitOnly = true),
        KnowledgeEntry("karh-008-source-limits", "What the source does and does not establish", "Methods", "", listOf("evidence-status", "limitations"), listOf("engagement_loops"), "Knowing how much weight these constructs can bear.", "The three constructs come from one author's recalled play of a small set of titles that treatment-seekers named, written down retrospectively without a formal qualitative method. The clinical links the paper raises are labelled hypotheses to be tested.", "Readers should treat the constructs as useful vocabulary for describing experiences, not as proven causes of gaming problems.", "Several reviewers of the paper raised concerns about method and engagement with related literature. The author states the constructs are starting points, not final.", "Bob's reading: use these ideas to talk about player feelings and to prompt questions, never as a reason to add or avoid a mechanic on their own.", "Would you like me to treat these as discussion prompts only, so that nothing here changes your design unless you choose it?", listOf("karh-007-design-experience-bond"), "high", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_CAVEAT", explicitOnly = true),
        KnowledgeEntry("karh-009-signal-density-and-session-shape", "Signal density and session length", "Analysis: ALERT", "", listOf("play-rhythm", "notifications", "signal-cues"), listOf("pacing", "engagement_loops"), "Matching how many attention signals a game shows to how long its sessions are meant to last.", "A mobile card game with timed chests and short return visits shows many highlighted signals on its home screen, while a series of long, focused single-player action games shows almost none and reserves them for essential information.", "The author notes that signal density tracks session shape: short frequent visits go with many cues, long absorbed sessions go with very few.", "In the mobile example the author considers the signal load excessive, and the busier design also carries purchase promotion. A comparison of two games is not a tested rule.", "Bob's reading: decide the intended session shape first, then let the interface be as quiet as that shape allows.", "Should your game be played in short returns during the day or in longer focused sittings?", listOf("karh-003-alert", "karh-004-chronotope-scale"), "medium", pilot = true, sourceId = "karhulahti2024", classification = "SOURCE_OBSERVATION", explicitOnly = true),
    )
}
